package org.eclipse.jface.text;

import java.util.HashMap;
import java.util.Map;

public class MultiStringMatcher {
    private static class Node {
        Map<Character, Node> children;
        String match;
        Node output;
        final int depth;

        Node(int depth) {
            this.depth = depth;
        }

        boolean hasChildren() {
            // Assume this method exists after initial refactoring
            return children != null;
        }
    }

    public void someMethod(Node s) {
        // Before: Direct field access
        if (s.children != null) {
            System.out.println("Node has children");
        }
    }
}

afterExample:
package org.eclipse.jface.text;

import java.util.HashMap;
import java.util.Map;

public class MultiStringMatcher {
    private static class Node {
        Map<Character, Node> children;
        String match;
        Node output;
        final int depth;

        Node(int depth) {
            this.depth = depth;
        }

        boolean hasChildren() {
            return children != null;
        }
    }

    public void someMethod(Node s) {
        // After: Using the accessor method
        if (s.hasChildren()) {
            System.out.println("Node has children");
        }
    }
}

