package org.eclipse.jface.text;

import java.util.List;

public class SomeOtherClass {
    private static class DifferentNode {
        List<String> children; // Different type, or no hasChildren() method

        DifferentNode(List<String> children) {
            this.children = children;
        }
    }

    public void anotherMethod(DifferentNode d) {
        // Should not match: d is not MultiStringMatcher.Node
        if (d.children != null) {
            System.out.println("Different node has children");
        }
    }
}
